import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'

// Apply after cap sync: android/ is regenerated by the build workflow.
const res = 'android/app/src/main/res'
const write_resource = async (path, content) => {
  await mkdir(dirname(join(res, path)), { recursive: true })
  await writeFile(join(res, path), content)
}

await mkdir(join(res, 'drawable-nodpi'), { recursive: true })
await copyFile('resources/branding/launcher-foreground.png', join(res, 'drawable-nodpi/rig_launcher_foreground.png'))
await copyFile('resources/branding/launcher-legacy.png', join(res, 'drawable-nodpi/rig_launcher_legacy.png'))

const adaptive_icon = `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
  <background android:drawable="@color/rig_launch_background" />
  <foreground android:drawable="@drawable/rig_launcher_foreground" />
</adaptive-icon>
`
await write_resource('values/rig_branding.xml', `<?xml version="1.0" encoding="utf-8"?>
<resources><color name="rig_launch_background">#111216</color></resources>
`)
await write_resource('mipmap-anydpi-v26/rig_launcher.xml', adaptive_icon)
await write_resource('mipmap-anydpi-v26/rig_launcher_round.xml', adaptive_icon)
const legacy_icon = `<?xml version="1.0" encoding="utf-8"?>
<bitmap xmlns:android="http://schemas.android.com/apk/res/android" android:src="@drawable/rig_launcher_legacy" android:gravity="fill" />
`
await write_resource('mipmap-anydpi/rig_launcher.xml', legacy_icon)
await write_resource('mipmap-anydpi/rig_launcher_round.xml', legacy_icon)
await write_resource('drawable/rig_launch_background.xml', `<?xml version="1.0" encoding="utf-8"?>
<layer-list xmlns:android="http://schemas.android.com/apk/res/android">
  <item android:drawable="@color/rig_launch_background" />
  <item android:width="240dp" android:height="240dp" android:gravity="center">
    <bitmap android:src="@drawable/rig_launcher_foreground" android:gravity="fill" />
  </item>
</layer-list>
`)

const manifest_path = 'android/app/src/main/AndroidManifest.xml'
const manifest = await readFile(manifest_path, 'utf8')
if (!manifest.includes('android:icon=') || !manifest.includes('android:roundIcon=')) {
  throw new Error('Unexpected Capacitor manifest: launcher icon attributes missing')
}
await writeFile(manifest_path, manifest
  .replace(/android:icon="[^"]*"/, 'android:icon="@mipmap/rig_launcher"')
  .replace(/android:roundIcon="[^"]*"/, 'android:roundIcon="@mipmap/rig_launcher_round"'))

const styles_path = join(res, 'values/styles.xml')
const styles = await readFile(styles_path, 'utf8')
const launch_style = /<style\b[^>]*name="AppTheme.NoActionBarLaunch"[^>]*>[\s\S]*?<\/style>/
if (!launch_style.test(styles)) throw new Error('Capacitor launch style not found')
await writeFile(styles_path, styles.replace(launch_style, `<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">
        <item name="windowSplashScreenBackground">@color/rig_launch_background</item>
        <item name="windowSplashScreenAnimatedIcon">@drawable/rig_launcher_foreground</item>
        <item name="postSplashScreenTheme">@style/AppTheme.NoActionBar</item>
        <item name="android:windowBackground">@drawable/rig_launch_background</item>
        <item name="android:statusBarColor">@color/rig_launch_background</item>
        <item name="android:navigationBarColor">@color/rig_launch_background</item>
        <item name="android:windowLightStatusBar">false</item>
    </style>`))
console.log('Applied hedgehog launcher, adaptive icon and native splash theme')
